"""matplotlib.tri — unstructured triangular grid support.

Provides Delaunay triangulation (via scipy.spatial when available,
fallback to a fan-based triangulation otherwise) plus the standard
``TriContourSet`` / ``TriInterpolator`` / ``TriAnalyzer`` / ``TriFinder``
classes that operate on a :class:`Triangulation`.
"""

import numpy as _np


class Triangulation:
    """A 2-D unstructured grid of triangles."""

    def __init__(self, x, y, triangles=None, mask=None):
        self.x = _np.asarray(x, dtype=float).ravel()
        self.y = _np.asarray(y, dtype=float).ravel()
        if self.x.shape != self.y.shape:
            raise ValueError("x and y must have the same length")
        if triangles is not None:
            self.triangles = _np.asarray(triangles, dtype=int)
            if self.triangles.ndim != 2 or self.triangles.shape[1] != 3:
                raise ValueError("triangles must be shape (M, 3)")
        else:
            self.triangles = _delaunay(self.x, self.y)
        self._mask = None
        if mask is not None:
            self.set_mask(mask)
        # Lazily-computed adjacency.
        self._edges = None
        self._neighbors = None
        self._trifinder = None

    def get_masked_triangles(self):
        if self._mask is None:
            return self.triangles
        return self.triangles[~self._mask]

    @property
    def mask(self):
        return self._mask

    @property
    def edges(self):
        """Return the (n_edges, 2) array of unique triangle edges."""
        if self._edges is None:
            tris = self.get_masked_triangles()
            edges = _np.vstack([tris[:, [0, 1]], tris[:, [1, 2]], tris[:, [2, 0]]])
            edges.sort(axis=1)
            # Dedupe rows.
            self._edges = _np.unique(edges, axis=0) if len(edges) else edges
        return self._edges

    @property
    def neighbors(self):
        """Per-triangle (3,) array of neighbor triangle indices; -1
        where the edge is on the convex hull."""
        if self._neighbors is None:
            tris = self.triangles
            n = len(tris)
            self._neighbors = -_np.ones((n, 3), dtype=int)
            # Build edge → triangle map.
            edge_map = {}
            for i, t in enumerate(tris):
                for j in range(3):
                    a, b = sorted((int(t[j]), int(t[(j + 1) % 3])))
                    edge_map.setdefault((a, b), []).append((i, j))
            for (a, b), occs in edge_map.items():
                if len(occs) == 2:
                    (t0, j0), (t1, j1) = occs
                    self._neighbors[t0, j0] = t1
                    self._neighbors[t1, j1] = t0
        return self._neighbors

    def set_mask(self, mask):
        if mask is None:
            self._mask = None
        else:
            self._mask = _np.asarray(mask, dtype=bool).ravel()
            if self._mask.shape != (len(self.triangles),):
                raise ValueError("mask length must match triangles")
        # Invalidate caches.
        self._edges = None
        self._neighbors = None

    def get_trifinder(self):
        if self._trifinder is None:
            self._trifinder = TrapezoidMapTriFinder(self)
        return self._trifinder

    @staticmethod
    def get_from_args_and_kwargs(*args, **kwargs):
        """Mirror upstream's "extract a Triangulation from positional
        plot args" helper: if ``args[0]`` is already a Triangulation,
        return it + the remaining args; otherwise build one from x/y
        (and optional triangles) and return + remaining args."""
        if args and isinstance(args[0], Triangulation):
            return args[0], args[1:]
        if len(args) >= 2:
            x, y = args[0], args[1]
            triangles = None
            rest_start = 2
            # Detect optional triangles array.
            if len(args) >= 3 and hasattr(args[2], '__iter__'):
                a3 = _np.asarray(args[2])
                if a3.ndim == 2 and a3.shape[1] == 3 and a3.dtype.kind in 'iu':
                    triangles = a3
                    rest_start = 3
            tri = Triangulation(x, y, triangles=triangles,
                                 mask=kwargs.pop('mask', None))
            return tri, args[rest_start:]
        raise ValueError("Need either a Triangulation or x, y arrays")


def _delaunay(x, y):
    """Compute a Delaunay triangulation of ``(x, y)``. Tries
    scipy.spatial.Delaunay first; falls back to a fan triangulation
    if scipy isn't available."""
    pts = _np.column_stack([x, y])
    try:
        from scipy.spatial import Delaunay
        return Delaunay(pts).simplices.astype(int)
    except Exception:
        # Fan triangulation around the first vertex — always valid for
        # convex point sets and gives at least *some* mesh for the
        # general case. Real Delaunay would be better but the shim
        # has to work without scipy.
        n = len(x)
        if n < 3:
            return _np.empty((0, 3), dtype=int)
        return _np.array([[0, i, i + 1] for i in range(1, n - 1)], dtype=int)


class TriContourSet:
    """Contour set computed from a :class:`Triangulation`."""

    def __init__(self, ax, *args, **kwargs):
        self.ax = ax
        self.axes = ax
        # Pop the triangulation off the front of args.
        self.triangulation, rest = (
            Triangulation.get_from_args_and_kwargs(*args, **kwargs)
            if args else (None, ()))
        self.z = _np.asarray(rest[0], dtype=float) if rest else None
        self.levels = list(kwargs.get('levels', []))
        self.cmap = kwargs.get('cmap', None)
        self.norm = kwargs.get('norm', None)
        self.alpha = kwargs.get('alpha', None)
        self.filled = kwargs.get('filled', False)
        self.collections = []


class UniformTriRefiner:
    """Refine a triangulation by uniformly subdividing each triangle
    into ``4 ** subdiv`` children."""

    def __init__(self, triangulation):
        self.triangulation = triangulation

    def refine_triangulation(self, subdiv=3, return_tri_index=False):
        """Subdivide each triangle ``subdiv`` times. Each subdivision
        splits one triangle into 4 by inserting midpoints on each edge."""
        tri = self.triangulation
        x, y = list(tri.x), list(tri.y)
        triangles = tri.triangles.tolist()
        parent_index = list(range(len(triangles)))
        for _ in range(int(subdiv)):
            new_tris = []
            new_parent = []
            mid_cache = {}
            def _mid(a, b):
                key = (min(a, b), max(a, b))
                if key not in mid_cache:
                    x.append((x[a] + x[b]) * 0.5)
                    y.append((y[a] + y[b]) * 0.5)
                    mid_cache[key] = len(x) - 1
                return mid_cache[key]
            for t_idx, (a, b, c) in enumerate(triangles):
                m_ab, m_bc, m_ca = _mid(a, b), _mid(b, c), _mid(c, a)
                new_tris += [[a, m_ab, m_ca], [m_ab, b, m_bc],
                              [m_ca, m_bc, c],  [m_ab, m_bc, m_ca]]
                new_parent += [parent_index[t_idx]] * 4
            triangles = new_tris
            parent_index = new_parent
        new_tri = Triangulation(x, y, triangles=triangles)
        if return_tri_index:
            return new_tri, _np.asarray(parent_index, dtype=int)
        return new_tri

    def refine_field(self, z, triinterpolator=None, subdiv=3):
        """Refine the triangulation AND the per-vertex field ``z``."""
        new_tri = self.refine_triangulation(subdiv=subdiv)
        # Linearly interpolate z onto the new vertices.
        if triinterpolator is None:
            triinterpolator = LinearTriInterpolator(self.triangulation, z)
        new_z = triinterpolator(new_tri.x, new_tri.y)
        return new_tri, new_z


class TriInterpolator:
    """Base for per-vertex value interpolation over a Triangulation."""

    def __init__(self, triangulation, z, trifinder=None):
        self.triangulation = triangulation
        self.z = _np.asarray(z, dtype=float).ravel()
        if len(self.z) != len(triangulation.x):
            raise ValueError("z length must match number of vertices")
        self._trifinder = trifinder or triangulation.get_trifinder()


class LinearTriInterpolator(TriInterpolator):
    """Piecewise-linear barycentric interpolation."""

    def __call__(self, x, y):
        x = _np.asarray(x, dtype=float)
        y = _np.asarray(y, dtype=float)
        # For each query point, locate the containing triangle and
        # compute barycentric coords against its vertices.
        tris = self.triangulation.triangles
        vx = self.triangulation.x; vy = self.triangulation.y
        out = _np.full(x.shape, _np.nan)
        flat_x = x.ravel(); flat_y = y.ravel()
        flat_out = out.ravel()
        # Brute-force search across triangles — fine for the shim's
        # accuracy needs; scipy-based finder would be faster.
        for i, (px, py) in enumerate(zip(flat_x, flat_y)):
            for tri in tris:
                a, b, c = tri
                bx0, by0 = vx[a], vy[a]
                bx1, by1 = vx[b], vy[b]
                bx2, by2 = vx[c], vy[c]
                denom = ((by1 - by2) * (bx0 - bx2)
                         + (bx2 - bx1) * (by0 - by2))
                if abs(denom) < 1e-15:
                    continue
                w0 = ((by1 - by2) * (px - bx2) + (bx2 - bx1) * (py - by2)) / denom
                w1 = ((by2 - by0) * (px - bx2) + (bx0 - bx2) * (py - by2)) / denom
                w2 = 1 - w0 - w1
                if -1e-9 <= w0 <= 1 + 1e-9 and -1e-9 <= w1 <= 1 + 1e-9 \
                        and -1e-9 <= w2 <= 1 + 1e-9:
                    flat_out[i] = w0 * self.z[a] + w1 * self.z[b] + w2 * self.z[c]
                    break
        return out


class CubicTriInterpolator(TriInterpolator):
    """Cubic interpolation — falls back to linear in the shim since
    cubic requires per-vertex gradient estimation which scipy / FEM
    isn't guaranteed to be available."""

    def __init__(self, triangulation, z, kind='min_E', trifinder=None, dz=None):
        super().__init__(triangulation, z, trifinder)
        self.kind = kind
        self.dz = dz
        self._linear = LinearTriInterpolator(triangulation, z, trifinder)

    def __call__(self, x, y):
        return self._linear(x, y)


class TriAnalyzer:
    """Geometric analysis of a triangulation — circle-ratio quality,
    flat-triangle masking, etc."""

    def __init__(self, triangulation):
        self.triangulation = triangulation

    def circle_ratios(self, rescale=True):
        """Return the inscribed/circumscribed circle radius ratio for
        each triangle. 1.0 → equilateral, near 0 → degenerate."""
        tri = self.triangulation
        x, y = tri.x, tri.y
        ratios = _np.zeros(len(tri.triangles))
        for i, (a, b, c) in enumerate(tri.triangles):
            ax, ay = x[a], y[a]; bx, by = x[b], y[b]; cx, cy = x[c], y[c]
            la = _np.hypot(bx - cx, by - cy)
            lb = _np.hypot(ax - cx, ay - cy)
            lc = _np.hypot(ax - bx, ay - by)
            s = (la + lb + lc) * 0.5
            area = max(s * (s - la) * (s - lb) * (s - lc), 0) ** 0.5
            if area <= 0 or s <= 0:
                ratios[i] = 0.0; continue
            r_in = area / s
            r_out = la * lb * lc / max(4 * area, 1e-15)
            ratios[i] = 2 * r_in / max(r_out, 1e-15)
        if rescale:
            mx = ratios.max() or 1.0
            ratios = ratios / mx
        return ratios

    def get_flat_tri_mask(self, min_circle_ratio=0.01, rescale=True):
        """True for triangles whose circle ratio is below threshold —
        useful for filtering degenerate triangles before contouring."""
        return self.circle_ratios(rescale=rescale) < min_circle_ratio


class TriFinder:
    """Base class for "find the triangle containing this point"
    queries. Subclasses implement ``__call__(x, y)``."""

    def __init__(self, triangulation):
        self.triangulation = triangulation

    def __call__(self, x, y):
        """Brute-force search — return triangle index per query point,
        or -1 when the point is outside the mesh."""
        x = _np.asarray(x); y = _np.asarray(y)
        out = _np.full(x.shape, -1, dtype=int)
        vx, vy = self.triangulation.x, self.triangulation.y
        for i, (px, py) in enumerate(zip(x.ravel(), y.ravel())):
            for ti, (a, b, c) in enumerate(self.triangulation.triangles):
                ax, ay = vx[a], vy[a]; bx, by = vx[b], vy[b]; cx, cy = vx[c], vy[c]
                d1 = (px - bx) * (ay - by) - (ax - bx) * (py - by)
                d2 = (px - cx) * (by - cy) - (bx - cx) * (py - cy)
                d3 = (px - ax) * (cy - ay) - (cx - ax) * (py - ay)
                neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
                pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
                if not (neg and pos):
                    out.ravel()[i] = ti
                    break
        return out


class TrapezoidMapTriFinder(TriFinder):
    """Faster TriFinder variant — upstream uses a trapezoidal map for
    O(log n) queries. The shim inherits the brute-force search."""
    pass
